<?php $title='Transparansi Desa'; require 'includes/header.php'; $rows=$pdo->query("SELECT * FROM documents WHERE kategori IN ('APBDes','Transparansi','Keuangan') ORDER BY tanggal DESC,id DESC")->fetchAll(); ?><section class="page-head"><div class="container"><h1 class="section-title">Transparansi Desa</h1><p class="text-muted">Dokumen dan informasi transparansi pemerintahan desa.</p></div></section><main class="container py-5"><div class="card card-soft p-4"><div class="table-responsive"><table class="table"><thead><tr><th>Dokumen</th><th>Kategori</th><th>Tanggal</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['judul'])?></td><td><?=e($r['kategori'])?></td><td><?=e($r['tanggal'])?></td><td><a class="btn btn-sm btn-outline-success" href="<?=e($r['file_path'])?>" target="_blank">Lihat</a></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><div class="alert alert-light">Belum ada dokumen transparansi.</div><?php endif;?></div></main><?php require 'includes/footer.php'; ?>
